mapper.sql:
emp00 AS ( SELECT t2.emp03_trans_id AS emp00_trans_id , t2.emp03_trans_date AS emp00_trans_date , CASE WHEN t2.emp03_trans_cd = '900' THEN t2.emp03_trans_date ELSE ( SELECT MIN(a.emp03_trans_date) - '1day'::interval FROM emp03_trans a WHERE a.emp03_person_id = t2.emp03_person_id AND a.emp03_trans_date > t2.emp03_trans_date ) END AS emp00_close_date , t2.emp03_person_id AS emp00_person_id , t2.emp03_pos_cd AS emp00_pos_cd , t2.emp03_trans_cd AS emp00_trans_cd , t2.emp03_title_cd AS emp00_title_cd , t2.emp03_trans_date AS emp00_date , t1.emp01_order_seq AS emp00_order_seq , t1.emp01_company_id AS emp00_company_id , t2.emp03_grade_cd AS emp00_grade_cd , t2.emp03_org_code_id AS emp00_org_code_id , t2.emp03_org_head_yn AS emp00_org_head_yn , t1.emp01_emp_no AS emp00_emp_no , t1.emp01_kor_nm AS emp00_kor_nm FROM emp01_person t1 INNER JOIN emp03_trans t2 ON t2.emp03_person_id = t1.emp01_person_id WHERE 1 = 1
AND t1.emp01_company_id = #{companyId}
AND t1.emp01_person_id = #{personId}
AND t2.emp03_trans_date = ( SELECT MAX(x.emp03_trans_date) FROM emp03_trans x WHERE x.emp03_person_id = t1.emp01_person_id AND ( (x.emp03_trans_cd = '900' AND x.emp03_trans_date < f_today()) OR (x.emp03_trans_cd != '900' AND x.emp03_trans_date <= f_today()) ) ) AND 'Y' = (CASE WHEN (SELECT COUNT(*) FROM emp04_add_title WHERE emp04_add_person_id = t1.emp01_person_id) = 0 THEN 'Y' ELSE (CASE WHEN (SELECT COUNT(*) FROM emp01_person a INNER JOIN emp04_add_title ON emp04_person_id = a.emp01_person_id WHERE emp04_add_person_id = t1.emp01_person_id) = 0 THEN 'N' ELSE 'Y' END) END) )
